package com.travbook.journeys.adapter.out.persistence;
import com.travbook.journeys.application.port.out.JourneyStore;
import com.travbook.journeys.application.port.in.Journeys.*;
import com.travbook.journeys.domain.model.Journey.*;
import com.travbook.shared.domain.DomainFailure;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class JdbcJourneyStore implements JourneyStore {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;
 public JdbcJourneyStore(JdbcClient j,TransactionTemplate t,ObjectMapper m,Clock c){jdbc=j;tx=t;json=m;clock=c;}
 private DomainFailure missing(){return new DomainFailure(NOT_FOUND,"Journey resource not found.");}
 public Optional<UUID> replay(UUID owner,String op,String key,String fingerprint){return jdbc.sql("select fingerprint,resource_id from journey_command where customer_id=:owner and operation=:op and command_key=:key").param("owner",owner).param("op",op).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"Idempotency key was used for different inputs.");return r.getObject(2,UUID.class);}).optional();}
 private boolean command(UUID owner,String op,String key,String fingerprint,UUID resource){return jdbc.sql("insert into journey_command(customer_id,operation,command_key,fingerprint,resource_id) values(:owner,:op,:key,:f,:id) on conflict do nothing").param("owner",owner).param("op",op).param("key",key).param("f",fingerprint).param("id",resource).update()==1;}
 private Quote ownedQuote(UUID owner,UUID id){return jdbc.sql("select payload::text from journey_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->json.readValue(s,Quote.class)).orElseThrow(this::missing);}
 public QuoteDetails quote(UUID owner,UUID id){var q=ownedQuote(owner,id);var accepted=jdbc.sql("select accepted_at from journey_acceptance where quote_id=:id").param("id",id).query((r,n)->r.getTimestamp(1).toInstant()).optional().orElse(null);var booking=jdbc.sql("select id from journey_booking where quote_id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(UUID.class).optional().orElse(null);return new QuoteDetails(q,accepted,booking,!clock.instant().isBefore(q.expiresAt()));}
 public Quote createQuote(Quote q,String key,String f,UUID c){return tx.execute(t->{if(!command(q.owner(),"QUOTE",key,f,q.id()))return ownedQuote(q.owner(),replay(q.owner(),"QUOTE",key,f).orElseThrow());q.valid(clock.instant());jdbc.sql("insert into journey_quote(id,customer_id,expires_at,payload) values(:id,:owner,:expires,cast(:p as jsonb))").param("id",q.id()).param("owner",q.owner()).param("expires",Timestamp.from(q.expiresAt())).param("p",json.writeValueAsString(q)).update();event(q.id(),1,"JourneyQuoteCreated",c,"CREATED","NONE","NONE","NONE");return q;});}
 private void lockQuote(UUID owner,UUID id){jdbc.sql("select id from journey_quote where id=:id and customer_id=:owner for update").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);}
 public void accept(UUID owner,UUID id,int version,String key,String f,UUID c){tx.executeWithoutResult(t->{if(!command(owner,"ACCEPT",key,f,id)){replay(owner,"ACCEPT",key,f).orElseThrow();return;}lockQuote(owner,id);var q=ownedQuote(owner,id);q.valid(clock.instant());if(q.version()!=version)throw new DomainFailure(QUOTE_VERSION_CONFLICT,"Accept the exact quote version.");if(jdbc.sql("insert into journey_acceptance(quote_id,accepted_at) values(:id,:now) on conflict do nothing").param("id",id).param("now",Timestamp.from(clock.instant())).update()==1)event(id,2,"JourneyQuoteAccepted",c,"ACCEPTED","NONE","NONE","NONE");});}
 public Booking book(UUID owner,UUID quote,List<Passenger> passengers,String email,Scenario scenario,String key,String f,UUID c){return tx.execute(t->{UUID id=UUID.randomUUID();if(!command(owner,"BOOK",key,f,id))return booking(owner,replay(owner,"BOOK",key,f).orElseThrow());lockQuote(owner,quote);var d=quote(owner,quote);if(d.acceptedAt()==null)throw new DomainFailure(QUOTE_NOT_ACCEPTED,"Accept this quote first.");if(d.bookingId()!=null)throw new DomainFailure(BOOKING_CONFLICT,"This quote already has a booking; open its saved status.");var b=Booking.create(id,d.quote(),d.acceptedAt(),passengers,email,scenario,c,clock.instant());jdbc.sql("insert into journey_booking(id,quote_id,customer_id,version,created_at,status,payload) values(:id,:q,:owner,1,:at,:s,cast(:p as jsonb))").param("id",id).param("q",quote).param("owner",owner).param("at",Timestamp.from(b.createdAt())).param("s",b.status().name()).param("p",json.writeValueAsString(b)).update();var terms=terms(quote);if(terms.fundingPlan()==com.travbook.journeys.domain.model.Care.Plan.DEPOSIT)jdbc.sql("insert into journey_balance(booking_id,state,amount,due_at) values(:id,'DUE',:amount,:due)").param("id",id).param("amount",terms.balanceAmount().decimal()).param("due",Timestamp.from(terms.balanceDue())).update();jdbc.sql("insert into journey_work(booking_id,state,next_at) values(:id,'READY',:due)").param("id",id).param("due",Timestamp.from(b.step()==Step.WAIT_PAYMENT?b.quote().expiresAt():clock.instant())).update();event(b);return b;});}
 public Booking booking(UUID owner,UUID id){return jdbc.sql("select payload::text from journey_booking where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->json.readValue(s,Booking.class)).orElseThrow(this::missing);}
 private void noCare(UUID id){if(jdbc.sql("select count(*) from journey_care_action where booking_id=:id and status in('PENDING','WAITING','REVIEW')").param("id",id).query(Integer.class).single()>0)throw new DomainFailure(BOOKING_CONFLICT,"Aftercare is already in progress.");}
 private Booking lock(UUID owner,UUID id){jdbc.sql("select booking_id from journey_work w join journey_booking b on b.id=w.booking_id where b.id=:id and b.customer_id=:owner for update of w,b").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);return booking(owner,id);}
 public Page list(UUID owner,UUID after){return page(owner,after,false);}
 public Page listAll(UUID owner,UUID after){return page(owner,after,true);}
 private Page page(UUID owner,UUID after,boolean all){String only=all?"":" and (payload->'quote'->>'version')::int=1";var q=jdbc.sql(after==null?"select payload::text from journey_booking where customer_id=:owner"+only+" order by created_at desc,id desc limit 21":"select payload::text from journey_booking where customer_id=:owner"+only+" and (created_at,id)<(:at,:cursor) order by created_at desc,id desc limit 21").param("owner",owner);if(after!=null){var b=booking(owner,after);q.param("at",Timestamp.from(b.createdAt())).param("cursor",after);}var rows=q.query(String.class).list().stream().map(s->json.readValue(s,Booking.class)).toList();return new Page(rows.stream().limit(20).toList(),rows.size()>20?rows.get(19).id():null);}
 private void save(Booking b,long previous){if(jdbc.sql("update journey_booking set version=:v,status=:s,payload=cast(:p as jsonb) where id=:id and version=:previous").param("v",b.version()).param("s",b.status().name()).param("p",json.writeValueAsString(b)).param("id",b.id()).param("previous",previous).update()!=1)throw new DomainFailure(BOOKING_CONFLICT,"Concurrent booking update.");}
 private void wake(Booking b){jdbc.sql("update journey_work set state=:state,attempts=0,next_at=:due,lease_token=null,lease_until=null where booking_id=:id").param("state",b.status()==Status.REVIEW?"REVIEW":b.step()==Step.DONE?"DONE":"READY").param("due",Timestamp.from(b.step()==Step.WAIT_PAYMENT?b.quote().expiresAt():clock.instant())).param("id",b.id()).update();}
 public Booking pay(UUID owner,UUID id,String key,UUID c){return tx.execute(t->{if(!command(owner,"PAY",key,id.toString(),id))return booking(owner,replay(owner,"PAY",key,id.toString()).orElseThrow());var b=lock(owner,id);var next=b.pay(clock.instant());save(next,b.version());wake(next);event(next);return next;});}
 private CancellationQuote readCancellation(UUID owner,UUID id){return jdbc.sql("select payload::text from journey_cancellation_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->json.readValue(s,CancellationQuote.class)).orElseThrow(this::missing);}
 public CancellationQuote cancellationQuote(UUID owner,UUID id,String key,UUID c){return tx.execute(t->{UUID qid=UUID.randomUUID();if(!command(owner,"CANCEL_QUOTE",key,id.toString(),qid))return readCancellation(owner,replay(owner,"CANCEL_QUOTE",key,id.toString()).orElseThrow());var locked=lock(owner,id);noCare(id);var q=locked.cancellationQuote(qid,clock.instant());jdbc.sql("insert into journey_cancellation_quote(id,booking_id,customer_id,payload) values(:id,:b,:owner,cast(:p as jsonb))").param("id",qid).param("b",id).param("owner",owner).param("p",json.writeValueAsString(q)).update();return q;});}
 public Booking cancel(UUID owner,UUID id,UUID q,boolean delay,String key,String f,UUID c){return tx.execute(t->{if(!command(owner,"CANCEL",key,f,id))return booking(owner,replay(owner,"CANCEL",key,f).orElseThrow());var b=lock(owner,id);noCare(id);var next=b.cancel(readCancellation(owner,q),delay,clock.instant());save(next,b.version());wake(next);event(next);return next;});}
 public Optional<Claim> claim(){return tx.execute(t->{var id=jdbc.sql("select booking_id from journey_work where state in('READY','RUNNING') and next_at<=:now and (lease_until is null or lease_until<clock_timestamp()) order by next_at,booking_id for update skip locked limit 1").param("now",Timestamp.from(clock.instant())).query(UUID.class).optional();if(id.isEmpty())return Optional.empty();UUID token=UUID.randomUUID();int attempts=jdbc.sql("update journey_work set state='RUNNING',attempts=attempts+1,lease_token=:token,lease_until=clock_timestamp()+interval '15 seconds' where booking_id=:id returning attempts").param("token",token).param("id",id.get()).query(Integer.class).single();var b=json.readValue(jdbc.sql("select payload::text from journey_booking where id=:id").param("id",id.get()).query(String.class).single(),Booking.class);return Optional.of(new Claim(b,token,attempts));});}
 private boolean owns(Claim c){return jdbc.sql("select booking_id from journey_work where booking_id=:id and state='RUNNING' and lease_token=:token and lease_until>clock_timestamp() for update").param("id",c.booking().id()).param("token",c.token()).query(UUID.class).optional().isPresent();}
 public boolean complete(Claim c,Booking next){return tx.execute(t->{if(!owns(c))return false;var b=lock(next.quote().owner(),next.id());if(b.version()!=c.booking().version())return false;if(next.status()==Status.REVIEW){jdbc.sql("insert into journey_review_checkpoint(booking_id,review_version,payload) values(:id,:v,cast(:p as jsonb))").param("id",next.id()).param("v",next.version()).param("p",json.writeValueAsString(b)).update();}save(next,b.version());wake(next);if(next.status()==Status.CONFIRMED&&terms(next.quote().id()).fundingPlan()==com.travbook.journeys.domain.model.Care.Plan.FULL)createDocument(next);if(next.status()==Status.FAILED||next.status()==Status.CANCELLED)jdbc.sql("update journey_balance set state='CANCELLED' where booking_id=:id and state in('DUE','OVERDUE')").param("id",next.id()).update();event(next);return true;});}
 public void retry(Claim c){if(c.attempts()>=(c.booking().step()==Step.REFUND_STATUS?20:5)){complete(c,c.booking().review(clock.instant()));return;}tx.executeWithoutResult(t->{if(!owns(c))return;jdbc.sql("update journey_work set state='READY',lease_token=null,lease_until=null,next_at=:due where booking_id=:id").param("due",Timestamp.from(clock.instant().plusMillis(Math.min(10000,c.attempts()*1500L)+Math.floorMod(c.booking().id().hashCode(),500)))).param("id",c.booking().id()).update();});}
 private void event(Booking b){event(b.id(),b.version(),"Journey"+b.status().name(),b.correlationId(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name());}
 private void event(UUID aggregate,long version,String type,UUID correlation,String status,String payment,String reservation,String refund){event(aggregate,version,type,correlation,status,payment,reservation,refund,UUID.nameUUIDFromBytes((aggregate+":"+version).getBytes(StandardCharsets.UTF_8)));}
 private void event(UUID aggregate,long version,String type,UUID correlation,String status,String payment,String reservation,String refund,UUID cause){UUID id=UUID.randomUUID();var e=new LinkedHashMap<String,Object>();e.put("eventId",id);e.put("aggregateId",aggregate);e.put("aggregateVersion",version);e.put("eventType",type);e.put("schemaVersion",1);e.put("timestamp",clock.instant());e.put("correlationId",correlation);e.put("causationId",cause);e.put("producer","journeys");e.put("mode","MOCK");e.put("payload",Map.of("status",status,"payment",payment,"reservation",reservation,"refund",refund));jdbc.sql("insert into journey_outbox(id,aggregate_id,aggregate_version,event_type,envelope) values(:id,:a,:v,:type,cast(:e as jsonb))").param("id",id).param("a",aggregate).param("v",version).param("type",type).param("e",json.writeValueAsString(e)).update();}
 private String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private void createDocument(Booking b){b.documentAllowed();var s=b.quote().selection();String content="TRAVBOOK MOCK "+s.request().kind()+" TICKET / VOUCHER\nNOT VALID FOR TRAVEL OR CHECK-IN. NO REAL RESERVATION OR PAYMENT.\nBooking: "+b.id()+"\nSupplier: "+s.supplier()+" / "+b.supplierReference()+"\n"+s.title()+"\nDeparture: "+s.departureAt()+" / "+s.timezone()+"\n"+String.join("\n",s.details())+"\n"+s.components().stream().map(c->c.description()+" INR "+c.amount().amount()).collect(java.util.stream.Collectors.joining("\n"))+"\n"+b.passengers().stream().map(p->"Passenger: "+p.name()).collect(java.util.stream.Collectors.joining("\n"))+"\nTotal INR "+s.total().amount()+"\n"+s.cancellationPolicy()+"\n";var d=new Document(UUID.randomUUID(),b.id(),clock.instant(),hash(content),content,"MOCK");jdbc.sql("insert into journey_document(id,booking_id,payload) values(:id,:b,cast(:p as jsonb)) on conflict(booking_id) do nothing").param("id",d.id()).param("b",b.id()).param("p",json.writeValueAsString(d)).update();}
 public Document document(UUID owner,UUID id){return tx.execute(t->{var b=lock(owner,id);b.documentAllowed();var d=jdbc.sql("select payload::text from journey_document where booking_id=:id").param("id",id).query(String.class).optional().map(s->json.readValue(s,Document.class)).orElseThrow(this::missing);if(!hash(d.content()).equals(d.sha256()))throw new IllegalStateException("Document integrity mismatch");return d;});}

 public List<com.travbook.shared.domain.Recovery.Case> reviews(Kind kind,int page){return jdbc.sql("select id from journey_booking where status='REVIEW' and payload->'quote'->'selection'->'request'->>'kind'=:kind order by created_at,id limit 20 offset :offset").param("kind",kind.name()).param("offset",page*20).query(UUID.class).list().stream().map(id->review(kind,id)).toList();}
 private Booking internal(Kind kind,UUID id){return jdbc.sql("select payload::text from journey_booking where id=:id and payload->'quote'->'selection'->'request'->>'kind'=:kind").param("id",id).param("kind",kind.name()).query(String.class).optional().map(p->json.readValue(p,Booking.class)).orElseThrow(this::missing);}
 public com.travbook.shared.domain.Recovery.Case review(Kind kind,UUID id){var b=internal(kind,id);var actions=jdbc.sql("select payload::text from journey_recovery_action where booking_id=:id order by created_at,id limit 3").param("id",id).query(String.class).list().stream().map(p->json.readValue(p,com.travbook.shared.domain.Recovery.Action.class)).toList();boolean available=b.status()==Status.REVIEW&&actions.size()<3&&jdbc.sql("select count(*) from journey_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",b.version()).query(Integer.class).single()==1;return new com.travbook.shared.domain.Recovery.Case(id,b.version(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name(),b.step().name(),available,b.updatedAt(),actions);}
 public Booking checkpoint(Kind kind,UUID id,long version){internal(kind,id);return jdbc.sql("select payload::text from journey_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",version).query(String.class).optional().map(p->json.readValue(p,Booking.class)).orElseThrow(()->new DomainFailure(BOOKING_CONFLICT,"No immutable checkpoint exists; do not infer an old workflow state."));}
 public Optional<com.travbook.shared.domain.Recovery.Action> recoveryReplay(String actor,String key,String fingerprint){return jdbc.sql("select fingerprint,payload::text from journey_recovery_action where actor=:actor and command_key=:key").param("actor",actor).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"Recovery key was used for different inputs.");return json.readValue(r.getString(2),com.travbook.shared.domain.Recovery.Action.class);}).optional();}
 public com.travbook.shared.domain.Recovery.Action resume(Kind kind,UUID id,long version,String actor,com.travbook.shared.domain.Recovery.Reason reason,String key,String fingerprint,UUID correlation){return tx.execute(t->{jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","journey-recovery:"+actor+":"+key).query((r,n)->true).single();var replay=recoveryReplay(actor,key,fingerprint);if(replay.isPresent())return replay.get();var original=internal(kind,id);var current=lock(original.quote().owner(),id);if(current.status()!=Status.REVIEW||current.version()!=version||!review(kind,id).recoverable())throw new DomainFailure(BOOKING_CONFLICT,"Review changed, lacks a checkpoint or exhausted its three recovery attempts.");var next=current.resumeFrom(checkpoint(kind,id,version),clock.instant());var action=new com.travbook.shared.domain.Recovery.Action(UUID.randomUUID(),id,next.version(),actor,reason,clock.instant());jdbc.sql("insert into journey_recovery_action(id,booking_id,actor,command_key,fingerprint,created_at,payload) values(:id,:booking,:actor,:key,:f,:at,cast(:p as jsonb))").param("id",action.id()).param("booking",id).param("actor",actor).param("key",key).param("f",fingerprint).param("at",Timestamp.from(action.createdAt())).param("p",json.writeValueAsString(action)).update();save(next,current.version());wake(next);event(id,next.version(),"JourneyReconciliationResumed",correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name(),action.id());return action;});}

 public com.travbook.journeys.domain.model.Care.Terms terms(UUID id){var stored=jdbc.sql("select payload::text from journey_terms where quote_id=:id").param("id",id).query(String.class).optional();if(stored.isPresent())return json.readValue(stored.get(),com.travbook.journeys.domain.model.Care.Terms.class);var q=jdbc.sql("select payload::text from journey_quote where id=:id").param("id",id).query(String.class).optional().map(p->json.readValue(p,Quote.class)).orElseThrow(this::missing);if(q.version()!=1)throw new IllegalStateException("Missing immutable enhanced terms");return com.travbook.journeys.domain.model.Care.Terms.of(q,com.travbook.journeys.domain.model.Care.Plan.FULL);}
 public Quote createAdvancedQuote(Quote q,com.travbook.journeys.domain.model.Care.Terms terms,String key,String fingerprint,UUID correlation){return tx.execute(t->{if(q.version()!=2||!terms.quoteId().equals(q.id()))throw new IllegalArgumentException("Enhanced quote binding");var saved=createQuote(q,key,"V2:"+fingerprint,correlation);if(saved.id().equals(q.id()))jdbc.sql("insert into journey_terms(quote_id,payload) values(:id,cast(:p as jsonb))").param("id",q.id()).param("p",json.writeValueAsString(terms)).update();return saved;});}
}
